def max_profit(price, k):
    """Write a function to find the maximum profit earned from a maximum of k stock transactions"""
    if not price or k <= 0:
        return 0
    n = len(price)
    if n < 2:
        return 0
    if k >= n // 2:
        return sum(max(0, price[i] - price[i - 1]) for i in range(1, n))
    prev = [0] * n
    for _ in range(k):
        curr = [0] * n
        max_diff = prev[0] - price[0]
        for i in range(1, n):
            curr[i] = max(curr[i - 1], price[i] + max_diff)
            max_diff = max(max_diff, prev[i] - price[i])
        prev = curr
    return prev[-1]
